INSERT INTO dbo.AssignmentGroups (GroupCode, GroupName, GroupNameAr, GroupEmail, GroupLeadEmployeeNumber, Description) VALUES
  (N'ITD-SD', N'Service Desk', N'مكتب الخدمة', N'servicedesk@wabibank.example', N'W1008', N'First line: calls, walk-ins and portal triage; laptops, desktops, printers, peripherals, office software and password resets.'),
  (N'ITD-INF', N'Infrastructure', N'البنية التحتية', N'itd-infrastructure@wabibank.example', N'W1230', N'Servers, databases, storage and backup, the email platform and the ATM fleet.'),
  (N'ITD-APP', N'Applications Support', N'دعم التطبيقات', N'itd-applications@wabibank.example', N'W1111', N'Core banking, digital banking, finance, HR and ITSM applications; core-banking user administration.'),
  (N'ITD-NET', N'Network', N'الشبكات', N'itd-network@wabibank.example', N'W1149', N'Branch WAN links, Head Office LAN and Wi-Fi, VPN and firewalls.'),
