INSERT INTO dbo.Services (ServiceCode, ServiceName, ServiceNameAr, OwningGroupCode, BusinessCriticality, Description) VALUES
  (N'CBS', N'Core Banking', N'النظام المصرفي الأساسي', N'ITD-APP', N'Critical', N'Customers, accounts, teller, loans, payments, clearing and the end-of-day batch.'),
  (N'DIGITAL', N'Digital Banking', N'الخدمات المصرفية الرقمية', N'ITD-APP', N'Critical', N'Mobile and internet banking, digital onboarding, OTP gateway and the contact-centre console.'),
  (N'FIN', N'Finance', N'النظام المالي', N'ITD-APP', N'High', N'General ledger, payables, procurement and budgeting.'),
  (N'HRMS', N'Personnel and Attendance', N'شؤون الموظفين والحضور', N'ITD-APP', N'Medium', N'Employee self-service, time and attendance and payroll.'),
  (N'EMAIL', N'Email and collaboration', N'البريد الإلكتروني والتعاون', N'ITD-INF', N'High', N'Mailboxes, distribution lists, Outlook and the email security gateway.'),
  (N'NETWORK', N'Network', N'الشبكة', N'ITD-NET', N'Critical', N'Head Office LAN and Wi-Fi, branch WAN and backup links, VPN and firewalls.'),
  (N'ATM', N'ATM network', N'شبكة الصرافات الآلية', N'ITD-INF', N'Critical', N'Branch ATMs and the ATM switch.'),
  (N'EUD', N'End-user devices', N'أجهزة المستخدمين', N'ITD-SD', N'Medium', N'Laptops, desktops, printers, peripherals, office software, file and print servers and the directory.'),
